using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using Frociart;
public static class FpgtTypesDumpTests {
 static string B(string value){return Convert.ToBase64String(Encoding.UTF8.GetBytes(value??""));}
 public static int Main(string[] args){try{string root=args[0];var rows=new List<string>();int count=0;foreach(string file in Directory.GetFiles(Path.Combine(root,"../expression-compat-qa/fixtures"),"*.frociart").OrderBy(x=>x,StringComparer.Ordinal)){string name=Path.GetFileNameWithoutExtension(file);var doc=DiagramIO.DecodeDocument(File.ReadAllBytes(file));var p=FlowSource.Compile(doc);if(!p.CanGenerate)continue;var t=new FlowFpgtTypes(p);foreach(var scope in t.Scopes.OrderBy(s=>s.Source.Id??"",StringComparer.Ordinal)){rows.Add(name+"\tSCOPE\t"+scope.Source.Id+"\t"+scope.ReturnType.Kind+"\t"+scope.ReturnType.Array.ToString().ToLowerInvariant());foreach(var s in scope.Symbols.OrderBy(s=>s.Name,StringComparer.Ordinal))rows.Add(name+"\tSYMBOL\t"+scope.Source.Id+"\t"+B(s.Name)+"\t"+s.NodeId+"\t"+s.Type.Kind+"\t"+s.Type.Array.ToString().ToLowerInvariant()+"\t"+s.Parameter+"\t"+s.Reference+"\t"+s.Declared+"\t"+s.Fixed+"\t"+s.Input+"\t"+s.ConstantPi+"\t"+s.Return+"\t"+s.InputChoice+"\t"+s.ArrayShape+"\t"+s.LiteralLength);}foreach(var issue in t.Issues.OrderBy(i=>i.Code+":"+i.NodeId,StringComparer.Ordinal))rows.Add(name+"\tISSUE\t"+issue.FunctionId+"\t"+issue.NodeId+"\t"+issue.Code+"\t"+B(issue.Message));count++;}File.WriteAllLines(Path.Combine(root,"types-csharp.tsv"),rows,new UTF8Encoding(false));Console.WriteLine("FPGT_TYPES_DUMP_CSHARP PASS programs="+count+" rows="+rows.Count);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
